"""
Module handling word-for-word translation of Luther's German Bible to English.

translateGerman( htmlStr:str ) -> str
    Do basic word-for-word translation from Luther's German Bible to English.
briefDemo() -> None
fullDemo() -> None
main calls fullDemo()


Maintenance instructions from the project owner (for future AI passes):
    * Expand ordinary vocabulary coverage across the whole Luther Bible, including
      rare and inflected forms. TEST books and reported examples are starting
      points, not the scope of a pass. Inspect the original German and the actual
      English output: apparent misspellings can be fragments created by an earlier
      replacement, rather than untranslated German words.
    * Use the meanings current in Luther's sixteenth-century German (the 1500s).
      Check uncertain readings in their verse context and historical dictionaries;
      a modern German meaning or a similar-looking English word can be misleading.
    * Concentrate on ordinary words when reviewing spelling-error lists. Ignore
      names, especially expected English name forms beginning with Y, and preserve
      existing name translations. Valid English words and regional spellings do
      not automatically require a new German translation entry.
    * Keep the table in general alphabetical order by the German source form,
      with longer forms before shorter forms that could consume their prefixes.
      Preserve necessary phrase and replacement-order exceptions, including rules
      that consume intermediate spellings. Respect case-sensitive matching and
      German noun capitalisation.
    * Do not add trailing spaces or punctuation variants merely because a word
      occurs before punctuation: an unrestricted source form already matches
      there. Guard an ending only when needed to protect a longer English word
      used elsewhere as a translation, or to preserve a demonstrated replacement
      dependency. Check the actual collision before adding or removing guards,
      and delete obsolete commented-out entries rather than retaining clutter.
    * Alternative translations may be separated by forward slashes, with the more
      likely/common meaning first (e.g., 'branch/twig'); use alternatives sparingly.
      Add a part of speech when it helps disambiguate an English gloss, using
      conventions such as love(n), love(v), fair(aj), and fair(n).
    * Check punctuation and HTML boundaries, capitalisation, longer-word
      collisions, and repeated or damaged English glosses. Review whole-corpus
      changes and retain focused regression cases for reported misses and
      historical meanings.
    * Distinguish contractions with es (e.g., habt‘s = have_it) from possessives.
      Opening brackets supply word-start boundaries. For reviewed ending guards,
      extend reviewedEndGuardWords below instead of adding duplicate '<' entries.

CHANGELOG:
    2026-10-20 Repair whole-Bible inflections, contractions, historical glosses and word boundaries
    2026-10-20 Translate beging in birthday accounts and correct the Schalksauge gloss
    2026-10-19 Document the owner's instructions for future vocabulary passes
    2026-10-17 Add missing part-of-speech labels to ambiguous English glosses
    2026-10-17 Translate Nuns before the shorter Nu rule can damage the name
    2026-10-17 Fix remaining TEST vocabulary and shorter-word replacement collisions
    2025-03-20 Moved into BOS from OBD (OpenBibleData)
    2026-10-16 Split German and Latin translations into separate modules
    2026-10-16 Expanded whole-Bible Luther vocabulary using historical senses
"""
