def translateGerman( htmlStr:str ) -> str:
    """
    Do basic word-for-word translation from Luther's German Bible to English.

    Text in htmlStr parameter can be inside a span,
        e.g., '<span class="Wycl_verseTextChunk">ech man in his seruice, and in the offring,</span>'
    """
    if (DEBUGGING_THIS_MODULE) or BibleOrgSysGlobals.debugFlag:
        fnPrint( DEBUGGING_THIS_MODULE, f"translateGerman( ({len(htmlStr)}) )" )

    # Handle common exception that can't be expressed in the word table
    # if htmlStr.endswith( ' alle') or htmlStr.endswith( ' ist'): htmlStr = htmlStr[:-1] # ' alle' at end goes to 'all' and 'ist' to 'is'
    # if htmlStr.startswith( 'und '):
    #     htmlStr = f'and {htmlStr[4:]}'
    htmlStr = htmlStr.replace( '»', '‘' ).replace( '«', '’' )
    # Give words after opening brackets the same boundary as words after spaces.
    # Mark only the spaces we insert, so original spacing survives unchanged.
    # Doing this once avoids two additional full-text scans for every table row.
    assert '\0' not in htmlStr
    htmlStr = re.sub( r'(?<=[(\[])(?=\w)', '\0 ', htmlStr )
    # Only extend reviewed ending guards to HTML/plain-text endings. Applying
    # every space-guarded rule there also consumes earlier English glosses:
    # e.g., Arm -> arm would then become "poor" under the German adjective arm.
    reviewedEndGuardWords = {
        'Ach','Barnaba','Bild','Christi','Dem','Du','Ehe','Enge','Harn','Huld',
        'Joch','Joas','Nu','Racha','Reh','Sarg','Wer',
        'aus','bitte','blinde','die Kost','feste','irrig','los','sei','uns',
        }
    for GermanWord,EnglishWord in GERMAN_WORD_MAP:
        if '(' in GermanWord or '[' in GermanWord:
            GermanWord = re.sub( r'(?<=[(\[])(?=\w)', '\0 ', GermanWord )
        htmlStr = htmlStr.replace( GermanWord, EnglishWord )
        if GermanWord[0] == ' ':
            if htmlStr.startswith( GermanWord[1:] ):
                htmlStr = htmlStr.replace( GermanWord[1:], EnglishWord[1:], 1 )
            htmlStr = htmlStr.replace( f'>{GermanWord[1:]}', f'>{EnglishWord[1:]}' )
        if GermanWord.endswith(' ') and GermanWord.strip() in reviewedEndGuardWords:
            # A closing HTML tag or the end of the input also ends a word.
            # Retain explicit punctuation rules where punctuation changes sense.
            source, target = GermanWord[:-1], EnglishWord[:-1]
            htmlStr = htmlStr.replace( f'{source}<', f'{target}<' )
            if htmlStr.endswith(source):
                htmlStr = htmlStr[:-len(source)] + target
            if GermanWord.startswith(' '):
                htmlStr = htmlStr.replace( f'>{source[1:]}<', f'>{target[1:]}<' )
                if htmlStr == source[1:]:
                    htmlStr = target[1:]

    htmlStr = htmlStr.replace( '\0 ', '' )
    # Whole-word matching also protects gloss components separated by underscores.
    return re.sub( r'[A-Za-z]+',
        lambda match: match[0] if match[0].lower() in _ENGLISH_WORDS_WITH_J
            else match[0].replace('j','y').replace('J','Y'), htmlStr )
# end of LutherGermanToEnglish.translateGerman



